async function fetchVideoBatch(){if(videoBatchFetching||!data.project_id)return;videoBatchFetching=true;try{const batch=await frontFetch('/api/video-batch?project_id='+encodeURIComponent(data.project_id));if(batch&&(!videoBatchPreview||['running','pausing','paused'].includes(batch.status))){currentVideoBatch=batch;const added=applyBatchResults(batch);if(added&&[2,4].includes(tab)){const player=tab===2?document.querySelector('#shotVideoPlayerSlot video'):null;if(player&&!player.paused&&!player.ended){player.addEventListener('ended',()=>{if(tab===2)render()},{once:true});updateBatchPanel();}else render();}else updateBatchPanel();}}catch(error){const box=document.querySelector('#videoBatchPanel');if(box)box.dataset.connectionError=error.message;}finally{videoBatchFetching=false;}}
const renderBeforeVideoBatch=render;render=function(){renderBeforeVideoBatch();attachVideoBatchPanel();};const requestVideoBeforeBatch=requestShotVideo;requestShotVideo=async function(target,draft=false){if(!draft&&videoBatchActive()&&currentVideoBatch.entries.some(e=>e.target_id===(target.shot_id||target.clip_id)&&['pending','preparing_frames','running','submitting'].includes(e.status))){toast('此视频已在批量队列中，不会重复提交');return}return requestVideoBeforeBatch(target,draft);};setInterval(()=>{if(videoBatchActive()||[2,4].includes(tab))void fetchVideoBatch()},4000);render();

